<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import AppIcon from '@/components/AppIcon.vue'
import CoverArt from '@/components/CoverArt.vue'
import PodcastCard from '@/components/PodcastCard.vue'
import { formatTime, formatDate } from '@/lib/format'
import type { RssEpisode } from '@/lib/rss'
import { usePlayerStore } from '@/stores/player'
import { queueItemFromEpisode, useQueueStore } from '@/stores/queue'
import { useAccountStore } from '@/stores/account'
import { useOfficialStore } from '@/stores/official'
import { useSubscriptionsStore, type Subscription } from '@/stores/subscriptions'
const rss = useSubscriptionsStore(), official = useOfficialStore(), account = useAccountStore(), player = usePlayerStore(), queue = useQueueStore()
const tab = ref<'official' | 'rss'>(account.isLoggedIn ? 'official' : 'rss'), url = ref(''), removing = ref(''), message = ref('')
const visibleCounts = ref<Record<string, number>>({})
function load(): void { if (account.isLoggedIn && official.listStatus === 'idle') void official.loadSubscriptions(); void rss.restore() }
onMounted(load); watch(() => account.isLoggedIn, () => { if (account.isLoggedIn) tab.value = 'official'; load() })
async function add(): Promise<void> { const result = await rss.addFromUrl(url.value); if (result.ok) url.value = '' }
function play(sub: Subscription, episode: RssEpisode, enqueue = false): void {
  if (!episode.audioUrl) return
  const entry = { id: 'rss:' + episode.id, title: episode.title, podcast: sub.feed?.title || 'RSS 播客', duration: episode.durationSeconds || 0, audioUrl: episode.audioUrl, source: 'rss' as const, imageUrl: sub.feed?.imageUrl }
  if (enqueue) { const item = queueItemFromEpisode(entry); if (item) message.value = queue.add(item) === 'added' ? '已加入播放队列' : '这集已经在队列中了' } else player.play(entry)
}
</script>
<template><section class="page"><header class="page-heading"><div><span class="eyebrow">SOUNDS YOU COME BACK TO</span><h1>我的声音收藏<span class="accent">.</span></h1><p>喜欢的节目，在这里慢慢听。</p></div><button class="button subtle" :disabled="official.listStatus === 'loading' || rss.refreshingAll" @click="tab === 'official' ? official.loadSubscriptions(true) : rss.refreshAll()"><AppIcon name="refresh" :size="16" />刷新订阅</button></header><div class="category-tabs"><button :class="{ active: tab === 'official' }" @click="tab = 'official'">小宇宙订阅<span v-if="official.count">{{ official.count }}</span></button><button :class="{ active: tab === 'rss' }" @click="tab = 'rss'">RSS 订阅<span v-if="rss.count">{{ rss.count }}</span></button></div><template v-if="tab === 'official'"><div v-if="!account.isLoggedIn" class="empty-state"><span class="feature-icon peach"><AppIcon name="library" :size="30" /></span><h2>你喜欢的声音，等你回来</h2><p>连接小宇宙账号，查看你已经订阅的播客。</p><RouterLink to="/official" class="button primary">连接我的账号<AppIcon name="arrow" :size="16" /></RouterLink></div><p v-else-if="official.listStatus === 'loading'" class="loading-message">正在加载你的订阅…</p><div v-else-if="official.listStatus === 'error'" class="notice error" role="alert">{{ official.listError }}<button class="text-button" @click="official.loadSubscriptions()">重试</button></div><div v-else-if="!official.count" class="empty-state"><AppIcon name="library" :size="35" /><h2>收藏夹还很安静</h2><p>在小宇宙 App 订阅喜欢的播客后，点击刷新就能看到。</p><RouterLink to="/discover" class="button subtle">去发现好声音</RouterLink></div><div v-if="account.isLoggedIn && official.count" class="podcast-grid"><PodcastCard v-for="podcast in official.podcasts" :key="podcast.pid" :podcast="podcast" /></div><button v-if="official.hasMore && account.isLoggedIn" class="button subtle load-more" :disabled="official.loadingMore" @click="official.loadMoreSubscriptions()">{{ official.loadingMore ? '加载中…' : '加载更多播客' }}</button></template><template v-else><form class="rss-form" @submit.prevent="add"><span class="feature-icon sage"><AppIcon name="rss" :size="22" /></span><div class="rss-form-fields"><label for="rss-url">把喜欢的播客，带到这里</label><div class="input-row"><input id="rss-url" v-model="url" type="url" placeholder="粘贴播客 RSS 订阅地址" required :disabled="rss.adding" /><button class="button primary" :disabled="rss.adding || !url.trim()"><AppIcon name="plus" :size="16" />{{ rss.adding ? '添加中…' : '添加订阅' }}</button></div><small>支持 RSS 2.0 与 Atom，订阅地址仅保存在本机。</small></div></form><p v-if="rss.addError || rss.persistenceError" class="notice error" role="alert">{{ rss.addError || rss.persistenceError }}</p><p v-if="message" class="notice compact" role="status">{{ message }}</p><p v-if="rss.restoring" class="loading-message">正在恢复你的 RSS 订阅…</p><div v-if="!rss.count && !rss.restoring" class="empty-state"><AppIcon name="rss" :size="38" /><h2>从一个订阅，开启一段陪伴</h2><p>在播客官网或分享菜单中复制 RSS 地址，粘贴到上方即可。</p></div><section v-for="sub in rss.items" :key="sub.url" class="rss-feed"><header class="rss-feed-head"><CoverArt :src="sub.feed?.imageUrl" :title="sub.feed?.title || 'RSS'" /><div class="grow"><h2>{{ sub.feed?.title || sub.url }}</h2><p class="muted">{{ sub.feed?.author || '独立的声音，自在地听' }}<span v-if="sub.feed"> · {{ sub.feed.totalEpisodes }} 集</span></p></div><button class="icon-button" :disabled="sub.status === 'loading'" title="刷新这个订阅" aria-label="刷新这个订阅" @click="rss.refresh(sub.url)"><AppIcon name="refresh" :size="17" /></button><button class="icon-button" title="移除这个订阅" aria-label="移除这个订阅" @click="removing = removing === sub.url ? '' : sub.url"><AppIcon name="trash" :size="17" /></button></header><div v-if="removing === sub.url" class="notice compact">从本机移除这个订阅？收听历史会保留。<button class="text-button text-danger" @click="rss.remove(sub.url); removing = ''">确认移除</button><button class="text-button" @click="removing = ''">取消</button></div><p v-if="sub.status === 'loading'" class="loading-message">正在获取最新单集…</p><p v-else-if="sub.error" class="notice error" role="alert">{{ sub.error }}</p><ul v-else class="episode-list"><li v-for="(episode, index) in (sub.feed?.episodes || []).slice(0, visibleCounts[sub.url] || 5)" :key="episode.id" class="episode-row"><span class="episode-index">{{ String(index + 1).padStart(2, '0') }}</span><div class="episode-copy"><h3>{{ episode.title || '未命名单集' }}</h3><p class="muted">{{ formatDate(episode.publishedAt) }} · {{ episode.durationSeconds ? formatTime(episode.durationSeconds) : '时长未知' }}</p><details v-if="episode.description" class="episode-description"><summary>单集简介</summary><p>{{ episode.description }}</p></details></div><button class="icon-button" :disabled="!episode.audioUrl" :aria-label="'加入队列：' + episode.title" @click="play(sub, episode, true)"><AppIcon name="plus" :size="17" /></button><button class="round-play" :disabled="!episode.audioUrl" :aria-label="'播放：' + episode.title" @click="play(sub, episode)"><AppIcon name="play" :size="18" /></button></li></ul><button v-if="(sub.feed?.episodes.length || 0) > (visibleCounts[sub.url] || 5)" class="text-button load-more" @click="visibleCounts[sub.url] = (visibleCounts[sub.url] || 5) + 10">展开更多单集<AppIcon name="chevron" :size="15" /></button></section></template></section></template>
